use vstd::prelude::*;

verus! {

    // A pure‐spec predicate saying that res is the interleaving of s1, s2, s3.
    spec fn is_interleaving(
        s1: Seq<i32>, 
        s2: Seq<i32>, 
        s3: Seq<i32>, 
        res: Seq<i32>
    ) -> bool
        requires
            s1.len() == s2.len() && s2.len() == s3.len()
        {
            // length is exactly 3 * n
            res.len() == 3 * s1.len() &&
            // and for each index i < n, the triple (s1[i], s2[i], s3[i])
            // appears at res[3*i], res[3*i+1], res[3*i+2]
            forall |i: nat| i < s1.len() ==>
                res.index(3*i)     == s1.index(i) &&
                res.index(3*i + 1) == s2.index(i) &&
                res.index(3*i + 2) == s3.index(i)
        }

    // The verified interleaving function.
    fn interleave(
        s1: &Vec<i32>, 
        s2: &Vec<i32>, 
        s3: &Vec<i32>
    ) -> (res: Vec<i32>)
        // all three inputs have equal length n,
        // and we assume 3 * n fits in an i32
        requires
            s1.len() == s2.len() &&
            s2.len() == s3.len() &&
            s1.len() <= (i32::MAX as usize) / 3
        // and we ensure the result is exactly the interleaving
        ensures
            is_interleaving(s1.view(), s2.view(), s3.view(), res.view())
    {
        let n: usize = s1.len();
        // preallocate exactly 3*n elements
        let mut res: Vec<i32> = Vec::with_capacity(3 * n);
        let mut i: usize = 0;
        // build up res by pushing triples
        while i < n
            invariant
                // i never exceeds n
                i <= n,
                // we've already pushed exactly 3*i elements
                res.len() == 3 * i,
                // and for each j < i the prefix is correctly interleaved
                forall |j: nat| j < i ==>
                    res.view().index(3*j)     == s1.view().index(j) &&
                    res.view().index(3*j + 1) == s2.view().index(j) &&
                    res.view().index(3*j + 2) == s3.view().index(j),
                // the input vectors keep their length
                s1.len() == n,
                s2.len() == n,
                s3.len() == n
            decreases
                n - i
        {
            // safe because i < n
            let x1: i32 = s1[i];
            let x2: i32 = s2[i];
            let x3: i32 = s3[i];

            res.push(x1);
            res.push(x2);
            res.push(x3);

            // increment i so that res.len() == 3*i again
            i = i + 1;
        }
        res
    }
}

